from collections import deque
def comps(I):
    H,W=len(I),len(I[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if (r,c) in seen: continue
            v=I[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<H and 0<=b<W and (a,b) not in seen and I[a][b]==v:
                        seen.add((a,b)); q.append((a,b))
            out.append((v,cells))
    return out
